// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public {
        c = new MyContract();
        vm.deal(address(c), 100 ether);
    }

    function testFuzz_property(address receiver, uint96 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(receiver != msg.sender);
        vm.assume(receiver != address(c));
        uint256 amt = bound(uint256(amount), 1, 100 ether);
        uint256 before = receiver.balance;
        vm.deal(address(this), 0);
        c.sendTo(receiver, amt);
        assertEq(receiver.balance, before + amt);
    }
}
